DO $$
DECLARE
  n INTEGER;
BEGIN
  SELECT COUNT(*) INTO n FROM curriculum_repository_node_links WHERE method = 'Two independent AI labelling passes per space against that space''s own concepts, reading the Lehrplan wording kept on a private PC; links by shared concepts; 2 Nov 2026';
  IF n < 103 THEN
    RAISE WARNING 'Expected 103 seeded node links, found %. Check which stage or node ids are missing.', n;
  ELSE
    RAISE NOTICE '% seeded node links in place', n;
  END IF;
END $$;
